"""Chapter-grounded scenes; exact chronology is preserved where the novel states it."""
# Dates without an explicit in-text day are approximate scheduling anchors from chapter context.
# The source arc centers on 1971–72; do not treat these anchors as verified historical dates.
# id, date, recipients, title, body, choice A, effect A, callback A, choice B, effect B, callback B
SCENES = [
    # Ch. 141–142
    (5101, '1971.08.01', ['PKS', 'SVN'], '错放在陈庭清名下的方略', '朴世诚把错页推回去：“陈家人多，先让他带头。”陈庭清想解释方略不是自己写的，瞥见桌边摆着自家田产与家丁名册，只好改口说愿意守符吉。朴随即把武器、税额和家属安置列成担保，任命也按家产落定。陈庭清站在主位旁，最后还是点头接令。', '顺势授予陈家总司令名义。', "add_to_variable = { v65_personal_network = 5 } add_to_variable = { v65_contract_credit = 3 } SVN = { add_to_variable = { v65_private_wealth = 3 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } }", '陈家答应出人出粮，任命也开始围着土地转。', '重新审核各家方略与兵额。', "add_political_power = -30 SVN = { add_to_variable = { v65_island_trust = 3 } }", '审核耽误编组，大地主仍要求保留自家队伍。'),
    # Ch. 141–143
    (5102, '1971.08.05', ['PKS', 'SVN'], '按家产排出的团练名册', '朴世诚让平定豪强参加开卷评定，暗中按家产和族人数量分军阶、分武器；反G救国的口号替土地利益披上公义外衣。会上没人讨论山海据点是否守得住，大家只等配枪名单；朴则把地方税收、军火买卖和家族担保纳入同一安排。报名者把考试当成分家产的另一道手续。', '让大族各守一片乡镇。', "add_to_variable = { v65_personal_network = 6 } add_to_variable = { v65_contract_credit = 5 } SVN = { add_to_variable = { v65_private_wealth = 4 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } }", '大族交来名单与税款，枪支也按承诺送到。', '把兵额分给较小的乡镇队。', "add_political_power = -25 SVN = { add_to_variable = { v65_island_trust = 4 } }", '小队愿守路口，大族却私下扣留枪械。'),
    # Ch. 143
    (5103, '1971.08.20', ['PKS', 'SVN'], '卢泰愚的随身小瓶', '卢泰愚在符吉监督陈庭清，口头保证朴的机动部队会来救援，胸前却藏着让陈“风光战死”的毒药。陈以为自己只是代理，总顾问却把情况直接报往归仁。朴要的不是统一军队，而是每家都离不开韩军枪械和保护。药瓶由卢保管，撤退时也不得离身。', '交卢泰愚全权维持指挥。', "add_to_variable = { v65_personal_network = 4 } SVN = { add_to_variable = { v65_private_wealth = 2 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } }", '卢把名单和求援电报一并送到归仁。', '派参谋组核验团练战况。', "add_political_power = -20 v65_upgrade_signals = yes", '参谋组发现外围据点的报告彼此矛盾。'),
    # Ch. 144, 147
    (5104, '1971.09.01', ['PKS', 'SVN'], '两位女伴与一通急电', '电话响起时，朴世诚正陪两位越南女伴消遣。副官报告符吉遭到围攻，他先问：“打到归仁没有？”听说目标只是县城，朴放下话筒，吩咐707空运增援、只守不追，随后让侍从收拾桌面，继续享用午餐。副官站在门边等候新的口令。', '保留私宅班底，命707守城。', 'add_political_power = -15 SVN = { add_to_variable = { v65_private_comfort = 4 } add_to_variable = { v65_private_wealth = -2 } clamp_variable = { var = v65_private_comfort min = 0 max = 100 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } } add_to_variable = { v65_personal_network = 3 }', '侍从收拾房间，707稳住城内；外围据点仍告失守。', '结束消遣，亲自核定增援次序。', "add_political_power = -20 v65_upgrade_signals = yes SVN = { add_to_variable = { v65_private_comfort = -2 } clamp_variable = { var = v65_private_comfort min = 0 max = 100 } }", '参谋送来据点名单，追击部队仍被留在城内。'),
    # Ch. 147–152
    (5105, '1971.09.10', ['PKS', 'SVN'], '撤出符吉的胜利公报', '地道爆破声传来，707在符吉巷战中伤亡近百。朴世诚让卢泰愚先撤主力，陈庭清则被灌下毒酒、补枪收场。记者等在指挥部外，朴把战报推给崔顺勇：“写成诱敌进城，数字先照这份报。”崔顺勇接过稿子，按朴的数字重誊一遍。', '先撤韩军骨干，再发布捷报。', "add_political_power = 55 add_to_variable = { v65_personal_network = 4 } set_country_flag = v65_inflated_reports", '公报先抵达汉城，伤亡名册晚了几天才送到。', '把损失和撤退一并报上去。', "add_political_power = -20 subtract_from_variable = { v65_war_fatigue = 3 }", '上级要求补交说明，部队暂时没有得到嘉奖。'),
    # Ch. 155–162
    (5106, '1971.10.01', ['PKS', 'SVN'], '竹林寺招待席上的两位艺人', '金大勇一行抵达富国岛，朴世诚摆出酒席，又叫来两位女艺人。巡视员问起特需账目，朴笑着指向竹林寺：“先在那里歇两天，船票我来安排。”等客人离席，卫队已封住寺院周边；当晚的行动记录随后被改成登船离岛。崔顺勇在门外等候，手里攥着离岛名册。', '加开私宴，买两夜处置时间。', 'add_political_power = -15 SVN = { add_to_variable = { v65_private_comfort = 5 } add_to_variable = { v65_private_wealth = -3 } clamp_variable = { var = v65_private_comfort min = 0 max = 100 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } } add_to_variable = { v65_personal_network = 4 }', '艺人和侍从先离开，巡视组的登船记录随后被改写。', '停止宴请，让巡视组核账。', "add_political_power = -30 SVN = { add_to_variable = { v65_private_comfort = -2 } add_to_variable = { v65_island_trust = 5 } clamp_variable = { var = v65_private_comfort min = 0 max = 100 } clamp_variable = { var = v65_island_trust min = 0 max = 100 } }", '几笔军需转卖被记下，日海要求尽快结案。'),
    # Ch. 163–165
    (5107, '1971.10.15', ['SVN', 'PKS'], '把机器和家眷送上船', '巡视组失踪后，朴加快把平定豪强家眷、作坊和制造工具运往富国岛。港口、机场和训练区一同扩张，陆上工厂却一间间停工；朴把人口安置、设备搬迁和私人代理贸易捆成生意，岛上仓库也因此优先接收军需。岛上商号开始向日海申请运输合同。', '优先转移可交易资产与军需设备。', "add_to_variable = { v65_contract_credit = 8 } SVN = { add_to_variable = { v65_private_wealth = 7 } add_to_variable = { v65_island_trust = 4 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } clamp_variable = { var = v65_island_trust min = 0 max = 100 } }", '岛上仓库扩容，平定商户开始抱怨失去生计。', '先运家属与维修队，保留工厂开工。', "add_political_power = -30 v65_upgrade_logistics = yes SVN = { add_to_variable = { v65_island_trust = 3 } }", '迁移速度慢了，岛上维修能力却更完整。'),
    # Ch. 164
    (5108, '1971.11.01', ['SVN', 'PKS'], '第七水输的艇队', '朴俊炳把舟艇伪装成登陆船，带第七水输赴富国岛训练；417和706教官补上水上渗透课程，特攻潜艇也进入试验。艇队保留自有装备账，朴则承诺优先燃料和实战机会，要求把岛上港口当作长期前进基地。旅团还把试航报告交给朴亲自过目。', '把艇队交给卫队统一调遣。', "v65_upgrade_training = yes add_to_variable = { v65_personal_network = 4 }", '试训艇队获得优先燃料，海岸巡逻归入同一班子。', '保留旅团自有舟艇与教官。', "add_political_power = -20 v65_upgrade_logistics = yes", '旅团训练更稳定，但行动要另行协调。'),
    # Ch. 163–168
    (5109, '1971.11.15', ['SVN', 'PKS'], '保证金、三清与强劳', '富国岛对越南族入岛另收保证金，不缴者送审查并强制劳动；数千人被循环拘押。朴拒绝把岛上守军调去西贡，因为港口和资产转移需要武装保护。商人可用保证金换资格，其他人则在审查站和工地间轮转。西贡若要调兵，必须先与韩方协商。', '以审查与劳役补港口人手。', "SVN = { add_to_variable = { v65_private_wealth = 5 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } } add_to_variable = { v65_contract_credit = 4 }", '港口工程按期推进，逃亡者带走审查站的消息。', '缴保证金即可入岛，限制羁押期限。', "add_political_power = -35 SVN = { add_to_variable = { v65_island_trust = 6 } }", '新劳工少了些，商船和家属更愿意留下。'),
    # Ch. 166–168
    (5110, '1971.12.01', ['PKS', 'SVN'], '密码本换来的假内鬼', '赵民基缴获越共电台密码本，以真实军火运输作诱饵，再投放假内鬼情报；阮晋勇肃叛后查出第三纵队贪污，部队反而更严整。地主盘剥又把村民推向游击队，朴的离间让对手清出旧账，也给他们换上更可靠的干部。清出的空缺很快由更听命的干部补上。', '继续投放假情报牵制阮晋勇。', "v65_upgrade_signals = yes add_to_variable = { v65_personal_network = 4 }", '审查令让游击队短暂停顿，正规部队却接管空缺。', '利用密码本监视真实运输。', "add_political_power = -20 add_to_variable = { v65_contract_credit = 3 }", '监听更费时间，新调来的越共指挥官却没那么容易受骗。'),
    # Ch. 174–176
    (5111, '1972.01.01', ['PKS', 'SVN'], '昭胜船上的口供与名单', '707突袭昭胜船，救出四十多名被贩女性；梁西辟却把有背景的警海关人员包装成卧底，挑无背景者顶罪。朴的部下控制了口供和名单，拿它们牵制金咏三、交换释放人情。案卷里没有写明受害者后来去了哪里。释放名单随后被拿去交换政治人情。', '将人证和名单纳入自己的关系网。', 'add_political_power = -15 add_to_variable = { v65_personal_network = 6 } SVN = { add_to_variable = { v65_private_wealth = 3 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } }', '几名有势力的嫌疑人获释，案卷留在梁西辟手中。', '把获救者交给公开救助机构。', 'add_political_power = -25 SVN = { add_to_variable = { v65_island_trust = 5 } clamp_variable = { var = v65_island_trust min = 0 max = 100 } }', '救助记录留档，梁西辟抱怨办案失去了筹码。'),
    # Ch. 176–178
    (5112, '1972.01.20', ['PKS', 'SVN'], '赴日船上的最后一份命令', '金咏三在赴日船上遇害，实际动手者文成旭是706特工。朴向总统称他逃跑，让金大中的反对党与自己的情报网继续互相制衡；案子转交中央情报部后，朴仍把执行链和命令记录握在手里。朴把失踪说法留给总统，现场人员不得对外发言。', '压下真相，保留双方把柄。', "add_to_variable = { v65_personal_network = 7 } set_country_flag = v65_inflated_reports", '案子归入失踪，706保存了牵制党内高层的材料。', '把执行链交由内部审查。', "add_political_power = -30 SVN = { add_to_variable = { v65_park_trust = 3 } }", '审查拖慢行动，几名特工要求调离政治案件。'),
    # Ch. 185–189
    (5113, '1972.03.01', ['SVN', 'PKS'], '第五机动军的两套命令', '南越组建第五机动军，名义上由武原顺指挥，实际101特战团只听李威炎和许家洛。岛方借新军团进入西贡防区，成贺负责大陆情报；朴正熙戒严又让他们担心援助中断，岛上因此要求保留任命和守军控制权。岛方继续保留守备司令、港口和人事安排。', '承认岛方实控，换取部队留驻。', "SVN = { add_to_variable = { v65_island_trust = 7 } } add_to_variable = { v65_personal_network = 5 }", '101团守住岛与西贡联络线，名义军团暂时完整。', '派韩方联络官统一军令。', "add_political_power = -35 v65_upgrade_staff = yes SVN = { subtract_from_variable = { v65_island_trust = 3 } clamp_variable = { var = v65_island_trust min = 0 max = 100 } }", '作战命令更清楚，许家洛要求重谈任命权。'),
    # Ch. 190–194
    (5114, '1972.03.16', ['PKS'], '维新革命卫队草案', '维新戒严后，朴世诚推动卫队脱离常规军系、直接效忠总统，并拆分特战、海军与飞弹司令部。海外利益、日海订单和军官任命被绑在一起，首都机械化师团因旧部关系优先拿到考试名额。卫队军官因此能够绕过常规军团获得升迁。', '批准独立编制与专属采购。', "add_to_variable = { v65_personal_network = 7 } add_to_variable = { v65_contract_credit = 6 } add_political_power = 50", '卫队扩编加快，几家日海关联企业拿到长期订单。', '让国军参谋本部保留调度权。', "add_political_power = -40 v65_upgrade_staff = yes", '草案多了监督条款，部队任命谈判延长。'),
    # Ch. 198–207
    (5115, '1972.04.04', ['PKS'], '济州伏击与虚空核项目', '韩军以假电台引来朝鲜接应船，在济州全歼十余人；朴随后借核电名义推动819计划。专家估计造核还要十到二十年，他仍用项目向两边申请资源，CIA监督人员则被安置在基地查看进度。基地账目同时列着核电设备与秘密研究开支。', '把伏击与核计划都做成政绩。', "add_political_power = 70 add_to_variable = { v65_personal_network = 5 } add_to_variable = { v65_contract_credit = 5 } set_country_flag = v65_inflated_reports", '报纸刊出“死士首胜”，核基地预算也获续拨。', '先核实战果并压低核项目承诺。', "add_political_power = -35 v65_upgrade_signals = yes", '战果少了几行，CIA监督人员却增加了。'),
    # Ch. 211–218
    (5116, '1972.05.03', ['SVN', 'PKS'], '281高地的轮番反攻', '复活节攻势压到顺化，朴用逃兵与囚犯团反攻281高地，刻意不投入精锐；101团又以缴获军服伪造歼敌战果。雨晴转换和空袭决定推进节奏，军医的伤亡表却比公报诚实得多。朴只追问战果有没有按规定先报给司令部，吴光长则仍要求继续攻城。', '继续用轮换炮灰拖住806团。', "add_war_support = 0.03 add_to_variable = { v65_war_fatigue = 6 } add_to_variable = { v65_personal_network = 3 }", '高地暂稳，军医报告的伤亡比公报高出许多。', '把精锐留在预备队，改守公路。', "v65_upgrade_training = yes add_political_power = -25", '部队不再冲山头，公路两侧仍需增援。'),
    # Ch. 219–223
    (5117, '1972.05.15', ['SVN', 'PKS'], '难民营里的补充兵', '广治守军从俘虏、罪犯和百万规模难民营征补；101看守战俘，强迫投诚者杀害拒降者，营地也曾发生夺枪暴动。白天炮击推进，夜间越共游击队进城，军官仍把登记册当作可随时抽取的兵源。补进来的人员缺乏训练，轮换队伍也越发松散。', '把营地人员编入攻城梯队。', "add_manpower = 2500 add_to_variable = { v65_war_fatigue = 5 }", '攻城队伍补满，值守战俘营的警卫也不得不增加。', '只登记自愿投诚者并保留守营兵力。', "add_manpower = 500 add_political_power = -20 v65_upgrade_training = yes", '补兵慢下来，暴动风险也低了一些。'),
    # Ch. 229–234
    (5118, '1972.06.11', ['SVN', 'PKS'], '101团的声望与防空导弹', '越共806团把101团松懈误判为陷阱，突击后半小时便击溃其防线；赵朝伟逃往广治，防空导弹又击落朴的撤离直升机。美空军恢复轰炸后，朴仍不肯让东河部队撤退，命他们在高地等空投。护航机请求增加，前线调兵计划随之延后。', '把空运资源转给东河守军。', "v65_upgrade_logistics = yes add_to_variable = { v65_war_fatigue = 4 }", '伤员后送减少，东河高地的补给仍能维持。', '集中防空侦察，暂缓直升机轮换。', "v65_upgrade_signals = yes add_political_power = -20", '飞行员要求更多护航，广治指挥部只能就地固守。'),
    # Ch. 235–247
    (5119, '1972.06.26', ['SVN', 'PKS'], '提前宣布广治收复', '朴退到顺化，把广治交给吴光长守中心高地，调第四师增援；战斗尚未结束，他先向阮文绍报称全城收复。赵朝伟撤回富国岛，朴随后用新102团补位，嘉奖令比控制线更早抵达。朴只责怪101团没有提前报送战果，中心高地仍需补兵。', '按公报口径发奖并继续增援。', "add_political_power = 45 set_country_flag = v65_inflated_reports add_to_variable = { v65_contract_credit = 3 }", '嘉奖令先发出，城内交火声尚未停下。', '等控制线核实后再宣布。', "add_political_power = -20 v65_upgrade_signals = yes", '战报晚了几天，前线获得更准的兵力表。'),
    # Ch. 237, 245–247
    (5120, '1972.06.26', ['SVN', 'PKS'], '猎鼠行动的伞降名册', '富国岛训练102特战团，朴又把新世纪福音会成员送上“猎鼠行动”；三四百名缺乏伞训者在轰炸掩护下空降敌后，没有可靠撤出安排。宗教招募替代专业训练，行动照片却先被当作战果素材准备好。名单先列出突击人数，撤退船只一栏仍空着。', '扩大特战招募，接受高损耗。', "add_manpower = 1800 add_to_variable = { v65_war_fatigue = 6 } add_to_variable = { v65_personal_network = 4 }", '敌后总部遭到突袭，名单上的损失也迅速变长。', '先让102团完成训练和撤离预案。', "v65_upgrade_training = yes add_political_power = -25", '行动延后，岛上的新团获得完整训练周期。'),
    # Ch. 249
    (5121, '1972.06.27', ['PKS', 'SVN'], '拉波钦海滩的鱼竿', '海浪拍着拉波钦海滩，朴世诚守着几根鱼竿，旁边机枪手看海。他拉不动大鱼，便朝士兵一挥手：“开火！”鱼身被打成几段后，朴把鱼竿递给参谋，问起广治进展，又催吴光长尽快收复城市。崔顺勇拿起抄网，跟着朴一同收线。', '维持私人随行班底与海滩宴席。', 'add_political_power = -15 SVN = { add_to_variable = { v65_private_comfort = 7 } add_to_variable = { v65_private_wealth = 3 } add_to_variable = { v65_network_SVN = 3 } clamp_variable = { var = v65_private_comfort min = 0 max = 100 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } clamp_variable = { var = v65_network_SVN min = 0 max = 100 } }', '警卫照常轮班，通讯班替司令官接通前线电话。', '压缩宴席，把随行经费转给前线。', "add_political_power = -15 SVN = { subtract_from_variable = { v65_private_comfort = 3 } clamp_variable = { var = v65_private_comfort min = 0 max = 100 } }", '前线收到一批燃油，司令官少了几名随行侍者。'),
    # Ch. 249
    (5122, '1972.06.27', ['PKS', 'SVN'], '鱼虾刺身与烧烤架', '遮阳伞下摆着刺身、糕点和烧烤架，朴世诚举杯时，厨师与侍者仍在忙碌。通讯员报告广治尚未收复，朴放下酒杯说：“收复的日子不会远。”他吃完才听参谋谈增援，随行人员则把地图摊在餐桌旁。崔顺勇把电报放在餐桌边等候批示。', '照常摆宴，让通讯班筛选来电。', 'add_political_power = -15 SVN = { add_to_variable = { v65_private_comfort = 5 } add_to_variable = { v65_private_wealth = -3 } clamp_variable = { var = v65_private_comfort min = 0 max = 100 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } } add_to_variable = { v65_personal_network = 2 }', '吴光长的最新电报被送到餐桌旁。', '撤掉宴席桌，改作临时指挥点。', "add_political_power = -15 SVN = { subtract_from_variable = { v65_private_comfort = 3 } clamp_variable = { var = v65_private_comfort min = 0 max = 100 } }", '参谋把地图摊在遮阳伞下，厨师收起烧烤架。'),
    # Ch. 255, 262
    (5123, '1972.07.15', ['SVN', 'PKS'], '湄公河防线与富国岛账本', '朴世诚提出四道防线，最后一道依托湄公河，由富国岛海空军和港口供给支撑；防线之间仍要扶植乡镇武装消耗越共。他拒绝因平民被迫北迁而改变战役节奏，并要求调研组优先测绘西南岸工事。测绘组回报后，阮文绍要求尽快看到完整方案。', '集中军工与供给建设湄公河末线。', "v65_upgrade_logistics = yes SVN = { add_to_variable = { v65_private_wealth = 5 } add_to_variable = { v65_island_trust = 4 } clamp_variable = { var = v65_private_wealth min = 0 max = 100 } clamp_variable = { var = v65_island_trust min = 0 max = 100 } }", '岛上仓库扩建，湄公河沿岸开始测绘工事。', '把运输能力分给迁民与地方守备。', "add_political_power = -35 SVN = { add_to_variable = { v65_island_trust = 5 } } v65_upgrade_training = yes", '安置船期拖慢工事，沿线守备得到更多熟悉地形的居民。'),
    # Ch. 264–280
    (5124, '1972.08.09', ['PKS'], '“我们是来救你们的”', '三八线战斗后，朴世诚推动特别军事行动：卫队越境突击并带回北方居民，随后将行动包装成解救乡亲。卢泰愚把前线撤退写成有序反击，朴正熙又把战果改大；俘虏、交换谈判和宣传都成了下一轮行动筹码。北方俘虏的去留很快进入双方交换谈判。', '扩大战果宣传，保留俘虏作为谈判筹码。', "add_political_power = 60 add_to_variable = { v65_personal_network = 5 } set_country_flag = v65_inflated_reports", '电报送去总统府，交换名单和记者通稿一并起草。', '限定行动范围，优先安排人员交换。', "add_political_power = -30 v65_upgrade_signals = yes", '交换谈判开始，前线联络人员也被要求增加。'),
]
